    "questionAr": "افترض أن يتحرك جسيم على مسار حلزون أرخميدس بإحداثيات قطبية $r(t) = 4t\text{ م}$ و $\theta(t) = 3t\text{ راديان}$. احسب عجلته القطرية $a_r$ عند $t = 1\text{ ث}$.",
