      "3. At $t = 1\\text{ s}$, $r(1) = 4\\text{ m}$.",
      "4. Radial acceleration formula: $a_r = \\ddot{r} - r\\dot{\\theta}^2 = 0 - (4)(3^2) = -9(4) = -36\\text{ m/s}^2$."
