    "questionAr": "جسيم يتحرك على مسار منحنٍ عجلته المماسية $a_t = 4\\text{ م/ث}^2$ وعجلته العمودية $a_n = 4\\text{ م/ث}^2$. احسب قياس الزاوية $\\phi$ بين متجه العجلة الكلية ومماس المنحنى.",
