    "questionAr": "يتحرك جسيم بسرعة ثابتة $v = 15\\text{ م/ث}$ على مسار نصف قطر انحنائه $\\rho = 75\\text{ م}$. ما معدل تغير زاوية ميل متجه السرعة مع الزمن $\\dot{\\phi} = \\frac{d\\phi}{dt}$؟",
